    aWandererG = 0xE10EC48EF0192CC7ULL;
    aWandererH = 0xA921A43EF12996C8ULL;
    aWandererI = 0xC2442D86752F5548ULL;
    aWandererJ = 0xD6E22DB97C451852ULL;
    aWandererK = 0xB40CA46229BED7A3ULL;

    //
    KDF_A(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mKeySpawnBConstants), &(mDomainBundleInbuilt.mKeySpawnBSalts), ARX_STATE_VARS);
    //
    TwistFarm::Farm(pFarmSalt,
                    aHeartLaneA, aHeartLaneB, aHeartLaneC, aHeartLaneD, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeral.mKeySpawnBSalts,
                    &(mDomainBundleEphemeral.mKeySpawnBConstants));
    //
    KDF_B(pWorkSpace, pNonce, &(mDomainBundleEphemeral.mKeySpawnBConstants), &(mDomainBundleEphemeral.mKeySpawnBSalts), ARX_STATE_VARS);
    //
    TwistFarm::Farm(pFarmSalt,
                    aWoodLaneA, aWoodLaneB, aWoodLaneC, aWoodLaneD, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mKeySpawnBSalts,
                    &(pWorkSpace->mDomainBundle.mKeySpawnBConstants));
    //
    KDF_C(pWorkSpace, pNonce, &(pWorkSpace->mDomainBundle.mKeySpawnBConstants), &(pWorkSpace->mDomainBundle.mKeySpawnBSalts), ARX_STATE_VARS);
    //
    TwistFarm::Farm(pFarmSalt,
                    aCrystalLaneA, aCrystalLaneB, aCrystalLaneC, aCrystalLaneD, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeral.mKeySpawnBSalts,
                    &(mDomainBundleEphemeral.mKeySpawnBConstants));
    //
    KDF_D(pWorkSpace, pNonce, &(mDomainBundleEphemeral.mKeySpawnBConstants), &(mDomainBundleEphemeral.mKeySpawnBSalts), ARX_STATE_VARS);
    //
    TwistFarm::Farm(pFarmSalt,
                    aVaporLaneA, aVaporLaneB, aVaporLaneC, aVaporLaneD, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mKeySpawnBSalts,
                    &(pWorkSpace->mDomainBundle.mKeySpawnBConstants));
    //
    //
    ////////////////////////////////////////////////////////
    //
    // Twist
    //
    aIngress = 0xCAC4E773D53B68DCULL;
    aCarry = 0xCFBC11936CFCDDC4ULL;
    aWandererA = 0xCAB99D753A8C7790ULL;
    aWandererB = 0xE4DABDA59573EEECULL;
    aWandererC = 0xCD7FD49588BCAB5FULL;
    aWandererD = 0xA7F699C4F90A1E8DULL;
    aWandererE = 0x858D5764E0769DBEULL;
    aWandererF = 0xB15FAD6F8C47ED61ULL;
    aWandererG = 0x9289FE3BB6D9CBA7ULL;
    aWandererH = 0xAC6E0206AF1E6BC2ULL;
    aWandererI = 0xBE4FFD7F04BC8690ULL;
    aWandererJ = 0x8CDB95A254FD83D7ULL;
    aWandererK = 0x917F4B995A35E086ULL;

    //
    KDF_A(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mTwistConstants), &(mDomainBundleInbuilt.mTwistSalts), ARX_STATE_VARS);
    //
    TwistFarm::Farm(pFarmSalt,
                    aHeartLaneA, aHeartLaneB, aHeartLaneC, aHeartLaneD, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeral.mTwistSalts,
                    &(mDomainBundleEphemeral.mTwistConstants));
    //
    KDF_B(pWorkSpace, pNonce, &(mDomainBundleEphemeral.mTwistConstants), &(mDomainBundleEphemeral.mTwistSalts), ARX_STATE_VARS);
    //
    TwistFarm::Farm(pFarmSalt,
                    aWoodLaneA, aWoodLaneB, aWoodLaneC, aWoodLaneD, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mTwistSalts,
                    &(pWorkSpace->mDomainBundle.mTwistConstants));
    //
    KDF_C(pWorkSpace, pNonce, &(pWorkSpace->mDomainBundle.mTwistConstants), &(pWorkSpace->mDomainBundle.mTwistSalts), ARX_STATE_VARS);
    //
    TwistFarm::Farm(pFarmSalt,
                    aCrystalLaneA, aCrystalLaneB, aCrystalLaneC, aCrystalLaneD, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeral.mTwistSalts,
                    &(mDomainBundleEphemeral.mTwistConstants));
